178	/****************************************************************************
179	 * Name: fb_update
180	 *
181	 * Description:
182	 *   Notify the framebuffer driver that the content changed (for LCD
183	 *   drivers that need an explicit flush).
184	 *
185	 ****************************************************************************/
186	
187	static void fb_blit(uint32_t w, uint32_t h)
188	{
189	  struct lcddev_area_s area;
190	
191	  memset(&area, 0, sizeof(area));
192	  area.row_start = 0;
193	  area.row_end   = h - 1;
194	  area.col_start = 0;
195	  area.col_end   = w - 1;
196	  area.stride    = w * 2;          /* RGB565: 2 bytes/pixel */
197	  area.data      = (FAR uint8_t *)g_rgbbuf;
198	
199	  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
200	}
201	
202	/****************************************************************************
203	 * Name: yuyv_to_fb
204	 *
205	 * Description:
206	 *   Convert a YUYV 4:2:2 frame to the framebuffer's RGB565 format and
207	 *   blit it centered on the screen.
208	 *
209	 ****************************************************************************/
210	
211	static void yuyv_to_fb(FAR const uint8_t *yuyv, uint32_t len)
212	{
213	  uint32_t panel_w = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
214	  uint32_t panel_h = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
215	  uint32_t cpw = (panel_w < TEST_WIDTH)  ? panel_w : TEST_WIDTH;
216	  uint32_t cph = (panel_h < TEST_HEIGHT) ? panel_h : TEST_HEIGHT;
217	  uint32_t x;
218	  uint32_t y;
219	
220	  for (y = 0; y < cph; y++)
221	    {
222	      FAR const uint8_t *src = yuyv + y * TEST_WIDTH * 2;
223	      FAR uint16_t *dst = &g_rgbbuf[y * cpw];
224	
225	      if ((size_t)(y * TEST_WIDTH * 2) + cpw * 2 > len)
226	        {
227	          break;
228	        }
229	
230	      for (x = 0; x + 1 < cpw; x += 2)
231	        {
232	          int y0 = src[0];
233	          int u  = src[1] - 128;
234	          int y1 = src[2];
235	          int v  = src[3] - 128;
236	
237	          dst[x] = ((clamp8(y0 + ((179 * v) >> 7)) & 0xf8) << 8) |
238	                   ((clamp8(y0 - ((44 * u) >> 7) - ((91 * v) >> 7)) & 0xfc) << 3) |
239	                   (clamp8(y0 + ((227 * u) >> 7)) >> 3);
240	
241	          dst[x + 1] = ((clamp8(y1 + ((179 * v) >> 7)) & 0xf8) << 8) |
242	                       ((clamp8(y1 - ((44 * u) >> 7) - ((91 * v) >> 7)) & 0xfc) << 3) |
243	                       (clamp8(y1 + ((227 * u) >> 7)) >> 3);
244	
245	          src += 4;
246	        }
247	    }
248	
249	  fb_blit(cpw, cph);
250	}
