1322	static int uvc_sensor_start_capture(FAR struct imgsensor_s *sensor,
1323	                                    imgsensor_stream_type_t type,
1324	                                    uint8_t nr_datafmt,
1325	                                    FAR imgsensor_format_t *datafmts,
