405	+  /* Bytes per micro-frame: for high-bandwidth endpoints the controller may
406	+   * issue up to `mult` packets per micro-frame back-to-back, so one payload
407	+   * slot spans mult*maxpacket bytes.  For mult==1 this is just maxpacket.
408	+   */
409	+
410	+  uint32_t   per_uf = maxpkt * (epinfo->mult ? epinfo->mult : 1);
411	+  int        uf;
412	+
413	+  itd->epinfo = epinfo;
414	+  itd->buffer = buffer;
415	+  itd->buflen = ISOC_ITD_BUFSZ;
416	+  itd->result = -EBUSY;
417	+
418	+  bufphys = (uintptr_t)sunxi_physramaddr((uintptr_t)buffer);
419	+
420	+  /* Buffer Page Pointer List (bpl[0..6]) spans 7 physical 4K pages starting
421	+   * at the (page-aligned) base of this iTD's buffer.  ISOC_ITD_BUFSZ (8K)
422	+   * needs at most 3 pages, but program all 7 defensively.  The per-page base
423	+   * must be page-aligned; the per-transaction XOFFS supplies the low 12 bits.
424	+   */
425	+
426	+  {
427	+    uintptr_t pgbase = bufphys & ITD_BUFPTR_MASK;
428	+
429	+    itd->hw.bpl[0] = sunxi_swap32(
430	+      ((uint32_t)epinfo->devaddr << ITD_BUFPTR0_DEVADDR_SHIFT) |
431	+      ((uint32_t)epinfo->epno << ITD_BUFPTR0_ENDPT_SHIFT) |
432	+      (pgbase & ITD_BUFPTR_MASK));
433	+
434	+    itd->hw.bpl[1] = sunxi_swap32(
435	+      ((uint32_t)maxpkt << ITD_BUFPTR1_MAXPKT_SHIFT) |
436	+      (epinfo->dirin ? ITD_BUFPTR1_DIRIN : ITD_BUFPTR1_DIROUT) |
437	+      ((pgbase + 0x1000) & ITD_BUFPTR_MASK));
438	+
439	+    {
440	+      uint32_t multi_val = (epinfo->mult == 3) ? ITD_BUFPTR2_MULTI_3 :
441	+                           (epinfo->mult == 2) ? ITD_BUFPTR2_MULTI_2 :
442	+                                                 ITD_BUFPTR2_MULTI_1;
443	+      itd->hw.bpl[2] = sunxi_swap32(multi_val |
444	+                                    ((pgbase + 0x2000) & ITD_BUFPTR_MASK));
445	+    }
446	+
447	+    itd->hw.bpl[3] = sunxi_swap32((pgbase + 0x3000) & ITD_BUFPTR_MASK);
448	+    itd->hw.bpl[4] = sunxi_swap32((pgbase + 0x4000) & ITD_BUFPTR_MASK);
449	+    itd->hw.bpl[5] = sunxi_swap32((pgbase + 0x5000) & ITD_BUFPTR_MASK);
450	+    itd->hw.bpl[6] = sunxi_swap32((pgbase + 0x6000) & ITD_BUFPTR_MASK);
451	+  }
452	+
453	+  /* Program all 8 transactions: transaction i reads one payload (up to
454	+   * per_uf bytes) into buffer + i*per_uf.  The offset relative to the
455	+   * page-aligned base carries both the page-select (bits 12-14) and the
456	+   * X-offset (bits 0-11).  Payloads that would run past this iTD's buffer
457	+   * are left inactive (only reachable if mult>1 makes 8*per_uf exceed the
458	+   * per-iTD buffer; our uncompressed mult==1 stream never hits this).
459	+   */
460	+
461	+  for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
462	+    {
463	+      uint32_t slot_off = (uint32_t)uf * per_uf;
464	+      uint32_t off      = (uint32_t)(bufphys & 0xfff) + slot_off;
465	+      uint32_t pg       = off >> 12;
466	+      uint32_t page_off = off & 0xfff;
467	+      uint32_t flags;
468	+
469	+      /* bpl[0..6] map 7 pages from the page-aligned base.  A transaction
470	+       * whose data would cross beyond page 6 has no buffer pointer, so leave
471	+       * it inactive.  (With alt<=6: 8*3072=24576 < 7*4096, never triggers.)
472	+       */
473	+
474	+      if (off + per_uf > 7u * 4096u)
475	+        {
476	+          itd->hw.trans[uf] = 0;  /* No page mapping; leave inactive */
477	+          continue;
478	+        }
479	+
480	+      flags = (page_off & ITD_TRAN_XOFFS_MASK) |
481	+              ((pg << ITD_TRAN_PG_SHIFT) & ITD_TRAN_PG_MASK) |
482	+              (per_uf << ITD_TRAN_LENGTH_SHIFT) |
483	+              ITD_TRAN_STATUS_ACTIVE;
484	+
485	+      /* Interrupt on the last transaction of the iTD. */
486	+
487	+      if (uf == ISOC_ITD_UFRAMES - 1)
488	+        {
489	+          flags |= ITD_TRAN_IOC;
490	+        }
491	+
492	+      itd->hw.trans[uf] = sunxi_swap32(flags);
493	+    }
494	+
495	+  /* Set the next-link pointer for the chain. */
496	+
497	+  itd->hw.nlp = nlp;
498	+
499	+  up_clean_dcache((uintptr_t)&itd->hw,
500	+                  (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));
501	+  UP_DSB();
502	+}
