504	+/****************************************************************************
505	+ * Name: sunxi_ring_install
506	+ *
507	+ * Description:
508	+ *   Install the iTD ring into the periodic frame list: slot j maps to
509	+ *   itd[j % ISOC_ITD_POOL].  Each iTD's nlp points to the interrupt QH.
510	+ *   The controller visits one iTD per 1ms frame; with N=32 iTDs, each iTD
511	+ *   is revisited every 32ms, giving the consumer a comfortable window to
512	+ *   harvest and re-arm before the controller laps.
513	+ *
514	+ *   Caller must hold g_ehci.lock.
515	+ *
516	+ ****************************************************************************/
517	+
518	+static void sunxi_ring_install(void)
519	+{
520	+  int i;
521	+  int slot;
522	+  uint32_t qh_link = g_ring.nlp;
523	+
524	+  g_ring.ring_head = 0;
525	+  g_ring.f_head    = 0;
526	+  g_ring.f_tail    = 0;
527	+  g_ring.f_cnt     = 0;
528	+
529	+  for (i = 0; i < ISOC_ITD_POOL; i++)
530	+    {
531	+      FAR uint8_t *buffer = g_ring.buf + (size_t)i * ISOC_ITD_BUFSZ;
532	+      sunxi_itd_arm(i, buffer, qh_link);
533	+    }
534	+
535	+  for (slot = 0; slot < FRAME_LIST_SIZE; slot++)
536	+    {
537	+      int idx = slot % ISOC_ITD_POOL;
538	+      g_framelist[slot] =
539	+        sunxi_swap32(sunxi_physramaddr((uintptr_t)&g_itdpool[idx].hw)) |
540	+        PFL_TYP_ITD;
541	+    }
542	+
543	+  up_clean_dcache((uintptr_t)&g_framelist[0],
544	+                  (uintptr_t)&g_framelist[0] +
545	+                  FRAME_LIST_SIZE * sizeof(uint32_t));
546	+  UP_DSB();
547	+}
