549	+/****************************************************************************
550	+ * Name: sunxi_isoc_setup
551	+ *
552	+ * Description:
553	+ *   Build an iTD chain for the first frame and install it into the periodic
554	+ *   frame list.  The chain approach eliminates the slot%N modulo race: each
555	+ *   iTD appears in the frame list exactly once, so the controller visits it
556	+ *   once and never overwrites unread data.
557	+ *
558	+ *   Idempotent: on subsequent calls, only the user buffer is latched (the
559	+ *   chain runs continuously).
560	+ *
561	+ ****************************************************************************/
562	+
563	+static int sunxi_isoc_setup(struct sunxi_rhport_s *rhport,
564	+                            struct sunxi_epinfo_s *epinfo,
565	+                            uint8_t *buffer, size_t buflen)
566	+{
567	+  (void)rhport;
568	+
569	+  if (buffer == NULL || buflen == 0)
570	+    {
571	+      return -EINVAL;
572	+    }
573	+
574	+  /* If the ring is already running, just latch the caller buffer. */
575	+
576	+  if (g_ring.epinfo == epinfo && g_ring.buf != NULL)
577	+    {
578	+      g_ring.user_buf    = buffer;
579	+      g_ring.user_buflen = buflen;
580	+      return OK;
581	+    }
582	+
583	+  /* First transfer: allocate resources and install the ring. */
584	+
585	+  if (g_ring.buf == NULL)
586	+    {
587	+      g_ring.buf = kmm_memalign(4096,
588	+                      (size_t)ISOC_ITD_POOL * ISOC_ITD_BUFSZ);
589	+      if (g_ring.buf == NULL)
590	+        {
591	+          return -ENOMEM;
592	+        }
593	+    }
594	+
595	+  if (g_ring.fifo == NULL)
596	+    {
597	+      g_ring.fifo = kmm_memalign(64,

595	+  if (g_ring.fifo == NULL)
596	+    {
597	+      g_ring.fifo = kmm_memalign(64,
598	+                       (size_t)ISOC_FIFO_SLOTS * ISOC_FIFO_SLOTSZ);
599	+      if (g_ring.fifo == NULL)
600	+        {
601	+          return -ENOMEM;
602	+        }
603	+    }
604	+
605	+  g_ring.epinfo      = epinfo;
606	+  g_ring.user_buf    = buffer;
607	+  g_ring.user_buflen = buflen;
608	+  g_ring.maxpacket   = epinfo->maxpacket;
609	+  g_ring.nlp         = g_framelist[0];  /* periodic-QH link (swapped) */
610	+
611	+  sunxi_ring_install();
612	+
613	+  return OK;
614	+}
