616	+/****************************************************************************
617	+ * Name: sunxi_isoc_teardown
618	+ *
619	+ * Description:
620	+ *   Detach the ring from the periodic frame list, restoring every slot to
621	+ *   the interrupt QH link, and mark the ring inactive.  Called on endpoint
622	+ *   cancel/free.  The DMA buffer is retained for reuse.
623	+ *
624	+ ****************************************************************************/
625	+
626	+static void sunxi_isoc_teardown(void)
627	+{
628	+  if (g_ring.epinfo == NULL)
629	+    {
630	+      return;
631	+    }
632	+
633	+  /* Restore every frame-list slot to the interrupt QH link.  The iTD
634	+   * nlp pointers are stale but harmless — the controller follows the
635	+   * frame-list slot, and the QH link is what matters.
636	+   */
637	+
638	+  {
639	+    int slot;
640	+
641	+    for (slot = 0; slot < FRAME_LIST_SIZE; slot++)
642	+      {
643	+        g_framelist[slot] = g_ring.nlp;
644	+      }
645	+
646	+    up_clean_dcache((uintptr_t)&g_framelist[0],
647	+                    (uintptr_t)&g_framelist[0] +
648	+                    FRAME_LIST_SIZE * sizeof(uint32_t));
649	+    UP_DSB();
650	+  }
651	+
652	+  g_ring.epinfo   = NULL;
653	+  g_ring.user_buf = NULL;
654	+  g_ring.f_cnt    = 0;
655	+}
