1778	               * into individual payloads.
1779	               *
1780	               * NOTE: this wire-format MUST match the de-framer in
1781	               * usbhost_uvc.c; the two are a contract.
1782	               */
1783	
1784	              if (g_ring.f_cnt > 0)
1785	                {
1786	                  size_t packed = 0;
1787	
1788	                  while (g_ring.f_cnt > 0)
1789	                    {
1790	                      uint32_t len;
1791	                      uint32_t seq;
1792	                      uint8_t *src;
1793	                      irqstate_t flags;
1794	
1795	                      flags = enter_critical_section();
1796	                      len = g_ring.fifo_len[g_ring.f_head];
1797	                      seq = g_ring.fifo_seq[g_ring.f_head];
1798	                      src = g_ring.fifo +
1799	                            (size_t)g_ring.f_head * ISOC_FIFO_SLOTSZ;
1800	                      leave_critical_section(flags);
1801	
1802	                      /* Clamp a single payload to the FIFO slot size so the
1803	                       * 2-byte length prefix can never overflow u16.
1804	                       */
1805	
1806	                      if (len > ISOC_FIFO_SLOTSZ)
1807	                        {
1808	                          len = ISOC_FIFO_SLOTSZ;
1809	                        }
1810	
1811	                      /* Stop if this [u16 len][payload] entry won't fit in
1812	                       * the remaining caller buffer.  Leave the payload in
1813	                       * the FIFO for the next DRVR_TRANSFER.
1814	                       */
1815	
1816	                      if (packed + 2 + len > g_ring.user_buflen)
1817	                        {
1818	                          break;
1819	                        }
1820	
1821	                      /* DIAG: check sequence continuity (per payload). */
1822	
1823	                      {
1824	                        static uint32_t last_seq = 0xffffffff;
1825	                        static uint32_t reorder_cnt;
1826	
1827	                        if (last_seq != 0xffffffff && seq != last_seq + 1)
1828	                          {
1829	                            if ((reorder_cnt++ % 50) == 0)
1830	                              {
1831	                                syslog(LOG_ERR,
1832	                                  "REORDER: expected=%u got=%u delta=%d #%u\n",
1833	                                  last_seq + 1, seq,
1834	                                  (int)(seq - last_seq - 1), reorder_cnt);
1835	                              }
1836	                          }
1837	
1838	                        last_seq = seq;
1839	                      }
1840	
1841	                      /* Write the 2-byte little-endian length prefix, then
1842	                       * the payload bytes.
1843	                       */
1844	
1845	                      g_ring.user_buf[packed]     = (uint8_t)(len & 0xff);
1846	                      g_ring.user_buf[packed + 1] =
1847	                        (uint8_t)((len >> 8) & 0xff);
1848	                      memcpy(g_ring.user_buf + packed + 2, src, len);
1849	                      packed += 2 + len;
1850	
1851	                      /* Advance f_head and decrement f_cnt under critical
1852	                       * section (harvest in bottomhalf may be writing
1853	                       * f_tail/f_cnt concurrently).
1854	                       */
1855	
1856	                      flags = enter_critical_section();
1857	                      g_ring.f_head = (g_ring.f_head + 1) % ISOC_FIFO_SLOTS;
1858	                      g_ring.f_cnt--;
1859	                      leave_critical_section(flags);
1860	                    }
1861	
1862	                  /* Return the packed batch. */
1863	
1864	                  if (packed > 0)
1865	                    {
1866	                      epinfo->xfrd    = packed;
1867	                      epinfo->result  = OK;
1868	                      epinfo->iocwait = false;
1869	                      return epinfo->result;
1870	                    }
1871	                }
1872	
1873	              /* (2) Check for cancellation. */
1874

1874	
1875	              if (!epinfo->iocwait)
1876	                {
1877	                  return epinfo->result;
1878	                }
1879	
1880	              /* (3) FIFO empty: fallback harvest (in case the bottomhalf
1881	               * hasn't run yet or missed something), then wait.
1882	               */
1883	
1884	              sunxi_isoc_harvest();
1885	              if (g_ring.f_cnt > 0)
1886	                {
1887	                  continue;
1888	                }
1889	
1890	              /* Sleep up to 1 tick (~1ms).  The IOC bottomhalf posts iocsem
1891	               * when it harvests data, waking us early.
1892	               */
1893	
1894	              nxsem_tickwait_uninterruptible(&epinfo->iocsem, 1);
1895	
1896	              if (++spins > 8000)        /* ~8s watchdog */
1897	                {
1898	                  epinfo->xfrd    = 0;
1899	                  epinfo->result  = -EAGAIN;
1900	                  epinfo->iocwait = false;
1901	                  return epinfo->result;
1902	                }
1903	            }
1904	        }
1905	      else
1906	#endif
1907	        {
1908	          ret = nxsem_wait_uninterruptible(&epinfo->iocsem);
1909	        }
1910	
1911	      if (ret < 0)
1912	        {
1913	          break;
1914	        }
1915	    }
1916	
1917	  return ret < 0 ? ret : epinfo->result;
1918	}
