2921	 * Name: sunxi_isoc_harvest
2922	 *
2923	 * Description:
2924	 *   Scan completed iTDs from ring_head forward, copy payloads into the FIFO,
2925	 *   and re-arm each harvested iTD.  Called from the EHCI bottom-half (IOC
2926	 *   interrupt context) so that harvest is decoupled from the stream consumer.
2927	 *   Also called as a fallback from sunxi_ioc_wait when the FIFO is empty.
2928	 *
2929	 *   Critical sections protect FIFO metadata updates (f_tail, f_cnt,
2930	 *   ring_head) against concurrent reads from the serve path.  Bulk work
2931	 *   (dcache invalidate, memcpy, re-arm) runs outside critical sections.
2932	 *
2933	 ****************************************************************************/
2934	
2935	static void sunxi_isoc_harvest(void)
2936	{
2937	  int scan;
2938	  uint32_t per_uf = (uint32_t)g_ring.maxpacket *
2939	    (g_ring.epinfo->mult ? g_ring.epinfo->mult : 1);
2940	
2941	  for (scan = 0; scan < ISOC_ITD_POOL; scan++)
2942	    {
2943	      int idx;
2944	      struct sunxi_itd_s *itd;
2945	      bool active = false;
2946	      int uf;
2947	      irqstate_t flags;
2948	
2949	      flags = enter_critical_section();
2950	      idx = (g_ring.ring_head + scan) % ISOC_ITD_POOL;
2951	      leave_critical_section(flags);
2952	
2953	      itd = &g_itdpool[idx];
2954	
2955	      up_invalidate_dcache((uintptr_t)&itd->hw,
2956	        (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));
2957	
2958	      for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
2959	        {
2960	          if (sunxi_swap32(itd->hw.trans[uf]) &
2961	              ITD_TRAN_STATUS_ACTIVE)
2962	            {
2963	              active = true;
2964	              break;
2965	            }
2966	        }
2967	
2968	      if (active)
2969	        {
2970	          break;  /* Chronological boundary; stop harvest */
2971	        }
2972	
2973	      /* iTD completed: harvest its payloads into FIFO. */
2974	
2975	      up_invalidate_dcache((uintptr_t)itd->buffer,
2976	        (uintptr_t)itd->buffer +
2977	        (size_t)ISOC_ITD_UFRAMES * per_uf);
2978	
2979	      /* DIAG: count empty micro-frame slots on this completed iTD. */
2980	
2981	      {
2982	        static uint32_t d_itds;   /* completed iTDs seen */
2983	        static uint32_t d_empty;  /* empty micro-frame slots */
2984	        int ufd;
2985	
2986	        for (ufd = 0; ufd < ISOC_ITD_UFRAMES; ufd++)
2987	          {
2988	            uint32_t t = sunxi_swap32(itd->hw.trans[ufd]);
2989	            uint32_t r = (t & ITD_TRAN_LENGTH_MASK) >>
2990	                         ITD_TRAN_LENGTH_SHIFT;
2991	            if (r == 0)
2992	              {
2993	                d_empty++;
2994	              }
2995	          }
2996	
2997	        if ((++d_itds % 512) == 0)
2998	          {
2999	            syslog(LOG_ERR,
3000	              "ITDFILL: itds=%u empty_uf=%u (%u%% of %u slots)\n",
3001	              d_itds, d_empty,
3002	              d_empty * 100 / (d_itds * ISOC_ITD_UFRAMES),
3003	              d_itds * ISOC_ITD_UFRAMES);
3004	          }
3005	      }
3006	
3007	      for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
3008	        {
3009	          uint32_t tran = sunxi_swap32(itd->hw.trans[uf]);
3010	          uint32_t rem  = (tran & ITD_TRAN_LENGTH_MASK) >>
3011	                          ITD_TRAN_LENGTH_SHIFT;
3012	          bool err = (tran & (ITD_TRAN_STATUS_XACTERR |
3013	                              ITD_TRAN_STATUS_BABBLE |
3014	                              ITD_TRAN_STATUS_DBERROR)) != 0;
3015	
3016	          if (err || rem == 0)
3017	            {
3018	              continue;
3019	            }
3020	
3021	          /* DIAG: cumulative harvest counter */
3022	
3023	          {
3024	            static uint32_t h_pls;
3025	            static uint32_t h_bytes;
3026	
3027	            h_pls++;
3028	            h_bytes += rem;
3029	
3030	            if ((h_pls % 2000) == 0)
3031	              {
3032	                syslog(LOG_ERR, "HARVEST: pls=%u bytes=%u\n",
3033	                       h_pls, h_bytes);
3034	              }
3035	          }
3036	
3037	          flags = enter_critical_section();
3038	          if (g_ring.f_cnt < ISOC_FIFO_SLOTS)
3039	            {
3040	              static uint32_t seq;  /* monotonic payload counter */
3041	              uint16_t f_tail_local = g_ring.f_tail;
3042	              leave_critical_section(flags);
3043	
3044	              /* memcpy outside critical section */
3045	
3046	              {
3047	                uint32_t n = rem > ISOC_FIFO_SLOTSZ ?
3048	                             ISOC_FIFO_SLOTSZ : rem;
3049	                memcpy(g_ring.fifo +
3050	                         (size_t)f_tail_local * ISOC_FIFO_SLOTSZ,
3051	                       itd->buffer + (uint32_t)uf * per_uf, n);
3052	
3053	                /* Update FIFO metadata in critical section */
3054	
3055	                flags = enter_critical_section();
3056	                g_ring.fifo_len[f_tail_local] = (uint16_t)n;
3057	                g_ring.fifo_seq[f_tail_local] = seq++;
3058	                g_ring.f_tail =
3059	                  (f_tail_local + 1) % ISOC_FIFO_SLOTS;
3060	                g_ring.f_cnt++;
3061	                leave_critical_section(flags);
3062	              }
3063	            }
3064	          else
3065	            {
3066	              leave_critical_section(flags);
3067	              {
3068	                static uint32_t diag_full;
3069	                if ((diag_full++ % 200) == 0)
3070	                  {
3071	                    syslog(LOG_ERR, "HARVEST fifo full #%u\n",
3072	                           diag_full);
3073	                  }
3074	              }
3075	            }
3076	        }
3077	
3078	      /* Re-arm immediately so the controller keeps filling. */
3079	
3080	      {
3081	        FAR uint8_t *buffer = g_ring.buf +
3082	                              (size_t)idx * ISOC_ITD_BUFSZ;
3083	        sunxi_itd_arm(idx, buffer, g_ring.nlp);
3084	      }
3085	
3086	      /* Advance ring_head in critical section */
3087	
3088	      flags = enter_critical_section();
3089	      g_ring.ring_head =
3090	        (g_ring.ring_head + 1) % ISOC_ITD_POOL;
3091	      leave_critical_section(flags);
3092	    }
3093	}
