/****************************************************************************
 * Name: sunxi_chain_install
 *
 * Description:
 *   Install the iTD linked list into the periodic frame list.  Each iTD is
 *   inserted at exactly ONE entry (spaced ISOC_ITD_STRIDE apart), forming a
 *   chain: entry → itd → QH.  The controller processes each iTD for 8
 *   consecutive microframes; it NEVER revisits the same iTD.
 *
 *   With POOL=64 and stride=8, the first batch covers entries 0,8,16,...,504
 *   (microframes 0..511).  The harvest pipeline re-links completed iTDs at
 *   entries 512,520,...,1016 (microframes 512..1023) before the controller
 *   wraps around.
 *
 *   Caller must hold g_ehci.lock.
 *
 ****************************************************************************/

static void sunxi_chain_install(void)
{
  int i;
  int slot;
  uint32_t qh_link = g_ring.nlp;

  g_ring.harvest_slot = 0;
  g_ring.next_slot    = 0;
  g_ring.free_count   = 0;
  g_ring.f_head       = 0;
  g_ring.f_tail       = 0;
  g_ring.f_cnt        = 0;

  /* Clear all frame-list entries to the interrupt QH. */

  for (slot = 0; slot < FRAME_LIST_SIZE; slot++)
    {
      g_framelist[slot] = qh_link;
    }

  /* Arm all iTDs and link each at one frame-list entry. */

  for (i = 0; i < ISOC_ITD_POOL; i++)
    {
      FAR uint8_t *buffer = g_ring.buf + (size_t)i * ISOC_ITD_BUFSZ;

      sunxi_itd_arm(i, buffer, qh_link);

      slot = i * ISOC_ITD_STRIDE;
      g_framelist[slot] =
        sunxi_swap32(sunxi_physramaddr((uintptr_t)&g_itdpool[i].hw)) |
        PFL_TYP_ITD;
    }

  g_ring.next_slot = (ISOC_ITD_POOL * ISOC_ITD_STRIDE) % FRAME_LIST_SIZE;

  up_clean_dcache((uintptr_t)&g_framelist[0],
                  (uintptr_t)&g_framelist[0] +
                  FRAME_LIST_SIZE * sizeof(uint32_t));
  UP_DSB();
}

