                g_ring.f_cnt++;
                leave_critical_section(flags);
              }
            }
          else
            {
              leave_critical_section(flags);
              {
                static uint32_t diag_full;
                if ((diag_full++ % 200) == 0)
                  syslog(LOG_ERR, "HARVEST fifo full #%u\n", diag_full);
              }
            }
        }

      syslog(LOG_ERR, "H6: payloads harvested, re-arming itd[%d]\n", idx);

      /* Re-arm and re-link at next_slot. */

      {
        FAR uint8_t *buffer = g_ring.buf +
                              (size_t)idx * ISOC_ITD_BUFSZ;
        uint16_t link_slot;
        uint32_t link_val;

        sunxi_itd_arm(idx, buffer, g_ring.nlp);

        flags = enter_critical_section();
        link_slot = g_ring.next_slot;
        g_ring.next_slot = (link_slot + ISOC_ITD_STRIDE) %
                           FRAME_LIST_SIZE;
        leave_critical_section(flags);

        syslog(LOG_ERR, "H7: re-linking itd[%d] at slot %u\n",
               idx, link_slot);

        g_itdpool[idx].slot = link_slot;
        link_val = sunxi_swap32(
          sunxi_physramaddr((uintptr_t)&g_itdpool[idx].hw)) |
          PFL_TYP_ITD;

        g_framelist[link_slot] = link_val;
        up_clean_dcache((uintptr_t)&g_framelist[link_slot],
                        (uintptr_t)&g_framelist[link_slot] +
                        sizeof(uint32_t));
      }

      syslog(LOG_ERR, "H8: re-linked, advancing ring_head\n");

      /* Advance ring_head. */

      flags = enter_critical_section();
      g_ring.ring_head = (g_ring.ring_head + 1) % ISOC_ITD_POOL;
      leave_critical_section(flags);
    }

  syslog(LOG_ERR, "H9: harvest exit\n");
}

